int arr[6] = {2, 1, 5, 1, 3, 2};
int k = 3;

// 1. First window sum
int currentSum = 0;
for (int i = 0; i < k; i++) {
    currentSum += arr[i];
}
int maxSum = currentSum;
std::cout << "Initial Sum: " << currentSum << "\n";

// 2. Slide the window
for (int i = k; i < 6; i++) {
    currentSum += arr[i];     // Entering element
    currentSum -= arr[i - k]; // Leaving element
    std::cout << "Slide Sum: " << currentSum << "\n";
    maxSum = std::max(maxSum, currentSum);
}
